"""The logs-chain-v1 vector: regenerated byte for byte, and passed from the file itself."""

from __future__ import annotations

import json
import os
from collections.abc import Callable
from typing import Any

import pytest
from aweb_naapp.hooks.strictjson import Refused

from aweb_logs.chain import (
    Checkpoint,
    Genesis,
    Receipt,
    content_commitment,
    open_checkpoint,
    open_receipt,
)
from aweb_logs.verify import verify_chain

from .chain_vector import VECTOR_PATH, build_vector, read_chain_case, render, unb64

VECTOR: dict[str, Any] = json.loads(VECTOR_PATH.read_bytes())
OPENERS: dict[str, Callable[[bytes, str], Receipt | Checkpoint]] = {
    "receipt": open_receipt,
    "checkpoint": open_checkpoint,
}


@pytest.mark.skipif(os.environ.get("LOGS_WRITE_VECTOR") != "1", reason="set LOGS_WRITE_VECTOR=1")
def test_write_vector() -> None:
    VECTOR_PATH.write_bytes(render(build_vector()))


def test_the_vector_regenerates_byte_for_byte() -> None:
    assert VECTOR_PATH.read_bytes() == render(build_vector()), (
        "the committed logs-chain vector differs from the regenerated one; "
        "rewrite it only for a reviewed change"
    )


@pytest.mark.parametrize("entry", VECTOR["genesis_cases"])
def test_genesis_hashes_from_the_file(entry: dict[str, Any]) -> None:
    assert Genesis(**entry["genesis"]).hash() == entry["genesis_hash"]


@pytest.mark.parametrize("entry", VECTOR["commitment_cases"])
def test_commitments_from_the_file(entry: dict[str, Any]) -> None:
    commitment = content_commitment(
        unb64(entry["salt_b64url"]), unb64(entry["signing_bytes_b64url"]), entry["signature"]
    )
    assert commitment == entry["content_commitment"]


@pytest.mark.parametrize("entry", VECTOR["artefact_cases"]["positive"], ids=lambda e: e["name"])
def test_artefacts_open_from_the_file(entry: dict[str, Any]) -> None:
    opened = OPENERS[entry["artefact"]](unb64(entry["signing_bytes_b64url"]), entry["signature"])
    assert opened.fields() == entry["fields"]


@pytest.mark.parametrize("entry", VECTOR["artefact_cases"]["negative"], ids=lambda e: e["name"])
def test_artefacts_refused_from_the_file(entry: dict[str, Any]) -> None:
    with pytest.raises(Refused) as caught:
        OPENERS[entry["artefact"]](unb64(entry["signing_bytes_b64url"]), entry["signature"])
    assert caught.value.code == entry["error"]


@pytest.mark.parametrize("entry", VECTOR["chain_cases"], ids=lambda e: e["name"])
def test_chain_cases_from_the_file(entry: dict[str, Any]) -> None:
    case = read_chain_case(entry)
    assert case.genesis.hash() == entry["genesis_hash"]
    report = verify_chain(
        case.genesis,
        case.events,
        receipt_keys=frozenset(case.receipt_keys),
        checkpoint_keys=frozenset(case.checkpoint_keys),
        receipts=case.receipts,
        checkpoints=case.checkpoints,
    )
    assert report.to_json() == entry["report"]
